/**
 * `serve` and `dev`: run agents over HTTP. Cursor hosting starts engines
 * with `agent-sdk serve` and reads `agent-sdk --help` for the hosting flags, so keep
 * `--cloud-tools-url`, `--peers-url`, and `--no-control-plane` listed.
 */
import { spawn } from "node:child_process";
import { serve } from "../../../index.js";
import { CLI_COMMAND_NAME as CLI, PACKAGE_NAME, packageVersion } from "../../distribution.js";
import { loadAgentLocalEnv } from "../../local-env.js";
import { openBrowser } from "../../open-browser.js";
import { ENTER_RESTART_EXIT_CODE, isServeRestartedWorker, isServeRestartWorker, runEnterRestartSupervisor, } from "../../serve-restart.js";
import { clearTerminal, stdoutPalette } from "../../terminal-style.js";
import { defineCommand } from "../command.js";
import { CliUsageError } from "../errors.js";
import { apiKeyFlag, bearerTokenFlag, dirFlag, stateRootFlag } from "../flags.js";
const serveFlags = {
    ...dirFlag,
    port: {
        type: "string",
        value: "<n>",
        description: "Port to listen on (default 3000). When 3000 is taken, serve tries the next free port. An explicit --port fails instead.",
    },
    host: { type: "string", value: "<host>", description: "Host to bind (default 127.0.0.1)." },
    mode: {
        type: "string",
        choices: ["single", "multi"],
        description: "multi (default): slugged /<dir>/v1/* routes plus host /v1/health. single: unslugged /v1/* for one agent.",
    },
    dev: {
        type: "boolean",
        description: "Dev mode: mount POST /v1/dev/schedules/:scheduleId and turn off the cron runner.",
    },
    ...apiKeyFlag,
    ...stateRootFlag,
    "bearer-token": {
        type: "string",
        value: "<token>",
        description: "Require this bearer token on API routes.",
    },
    "allow-anonymous": {
        type: "boolean",
        description: "Admit all HTTP callers. Only behind a trusted network. Not with --bearer-token.",
    },
    "allow-anonymous-cursor-github": {
        type: "boolean",
        description: "Allow --allow-anonymous with githubChannel({ cursorAccount }). Callers can use the account's repo-scoped GitHub credential.",
    },
    "allow-anonymous-cursor-account-mcp": {
        type: "boolean",
        description: "Allow --allow-anonymous with defineConnection({ cursorAccount: true }). Callers can use the account's MCP connectors.",
    },
    "cursor-scm-proxy": {
        type: "boolean",
        description: "Send cursorAccount SCM API calls through the Cursor backend forwarder instead of minting raw tokens here.",
    },
    "public-url": {
        type: "string",
        value: "<url>",
        kind: "url",
        description: "Base URL where this host is reachable from outside.",
    },
    "no-schedules": { type: "boolean", description: "Turn off the cron runner outside dev mode." },
    "no-control-plane": {
        type: "boolean",
        description: "Do not start the bundled control plane (schedule and reminder clocks). Cursor hosting passes this.",
    },
    "no-playground": {
        type: "boolean",
        description: "Turn off the web playground at /playground (also skips its build and HMR).",
    },
    "no-docs": {
        type: "boolean",
        description: "Turn off the documentation site at /docs (also skips its build).",
    },
    "cloud-tools-url": {
        type: "string",
        value: "<url>",
        description: "Cursor hosting passes the deployment's server-tools MCP URL here. Hosting reads `agent-sdk --help` for this flag.",
    },
    "peers-url": {
        type: "string",
        value: "<url>",
        description: "Cursor hosting passes the base URL where a single-agent serve reaches its peers at <url>/<slug>/v1/mcp. Hosting reads `agent-sdk --help` for this flag.",
    },
    "cursor-events": {
        type: "boolean",
        description: "Pull SCM webhook events from /v0/scm-events as your Cursor user. Needs sign-in and --repo.",
    },
    repo: {
        type: "string",
        multiple: true,
        value: "<owner/name>",
        description: "With --cursor-events: a repository to subscribe to.",
    },
};
export const serveCommand = defineCommand({
    name: "serve",
    group: "develop",
    summary: "Serve agents over HTTP under /<slug>/... with an index at /.",
    description: `
On a TTY, press Enter to restart: the CLI starts again, so agent code, evals,
and the playground reload. Cursor hosting starts engines with this command.`,
    flags: serveFlags,
    effect: "interactive",
    examples: ["agent-sdk serve --dir ./agents", "agent-sdk serve --mode single --port 0"],
    async run({ values }) {
        return runServe(values.dir, values, false);
    },
});
export const devCommand = defineCommand({
    name: "dev",
    group: "develop",
    summary: "Serve the project for local development (serve --dev).",
    description: `
Dispatch schedules and reminders by hand, accept unsigned GitHub loopback
deliveries, and run the playground with Vite HMR. The path defaults to the
current folder.`,
    args: [{ name: "path", description: "Project root. Same as --dir." }],
    flags: {
        ...serveFlags,
        web: {
            type: "boolean",
            description: "Open the playground in a browser once the server is up.",
        },
    },
    effect: "interactive",
    examples: ["agent-sdk dev", "agent-sdk dev ./my-agent --web"],
    async run({ values, positionals, argv }) {
        const dirFlagPassed = argv.some((arg) => arg === "--dir" || arg.startsWith("--dir="));
        const positionalDir = positionals[0];
        if (positionalDir !== undefined && dirFlagPassed && values.dir !== positionalDir) {
            throw new CliUsageError("pass a path as a positional or --dir, not both");
        }
        return runServe(positionalDir ?? values.dir, values, true, values.web === true);
    },
});
async function runServe(serveDir, values, devCommand, openWeb = false) {
    const port = parsePort(values.port);
    if (values["allow-anonymous"] === true && values["bearer-token"] !== undefined) {
        throw new CliUsageError("--allow-anonymous and --bearer-token are mutually exclusive");
    }
    const dev = devCommand || values.dev === true;
    const style = stdoutPalette();
    // Real env wins (loadEnvFile never overrides). Runs inside start()
    // so dev's Enter-restart picks up tokens written since boot.
    const loadLocalEnv = () => {
        const loadedEnvFiles = loadAgentLocalEnv(serveDir);
        if (loadedEnvFiles.length > 0) {
            process.stdout.write(`${style.dim(`env: loaded ${loadedEnvFiles.join(", ")}`)}\n`);
        }
    };
    // The flag's choices reject other values. The literals are what serve() accepts.
    const mode = values.mode;
    const serveMode = mode === "single" ? "single" : mode === "multi" ? "multi" : undefined;
    const serveOptions = {
        port,
        host: values.host,
        mode: serveMode,
        dev,
        apiKey: values["api-key"],
        stateRoot: values["state-root"],
        authToken: values["bearer-token"],
        allowAnonymous: values["allow-anonymous"] === true ? true : undefined,
        allowAnonymousCursorGithub: values["allow-anonymous-cursor-github"] === true ? true : undefined,
        allowAnonymousCursorAccountMcp: values["allow-anonymous-cursor-account-mcp"] === true ? true : undefined,
        cursorScmProxy: values["cursor-scm-proxy"] === true ? true : undefined,
        schedules: values["no-schedules"] === true ? false : undefined,
        noControlPlane: values["no-control-plane"] === true ? true : undefined,
        playground: values["no-playground"] === true ? false : undefined,
        docs: values["no-docs"] === true ? false : undefined,
        publicUrl: values["public-url"],
        cloudToolsUrl: values["cloud-tools-url"],
        peersUrl: values["peers-url"],
        cursorEvents: values["cursor-events"] === true ? { repos: values.repo ?? [] } : undefined,
        // Soft boot logs stay secondary to the banner. `dim` is a no-op on
        // already-styled lines (the MCP warning box).
        logger: (line) => {
            process.stdout.write(`${style.dim(line)}\n`);
        },
    };
    const enterToRestart = process.stdin.isTTY;
    if (enterToRestart && !isServeRestartWorker()) {
        return runEnterRestartSupervisor({
            spawn: (command, args, spawnOptions) => spawn(command, args, spawnOptions),
            onRestart: () => {
                clearTerminal();
            },
        });
    }
    const bannerOpts = {
        noPlayground: values["no-playground"] === true,
        dev,
        bearerToken: values["bearer-token"] !== undefined,
        noSchedules: values["no-schedules"] === true,
    };
    const start = async () => {
        loadLocalEnv();
        const next = await serve(serveDir, serveOptions);
        printServeBanner(next, bannerOpts);
        if (enterToRestart) {
            process.stdout.write(style.dim("  press Enter to restart\n"));
        }
        return next;
    };
    const handle = await start();
    // Enter-restart respawns this worker; open the browser on the first start only.
    if (openWeb && !isServeRestartedWorker()) {
        const playgroundUrl = resolvePlaygroundBannerUrl(handle, bannerOpts.noPlayground);
        if (playgroundUrl !== undefined) {
            openBrowser(playgroundUrl);
        }
    }
    let closing = false;
    let restartRequested = false;
    await new Promise((resolve) => {
        const shutdown = () => {
            if (closing) {
                return;
            }
            closing = true;
            process.stdout.write("\nshutting down (draining running turns)\n");
            void handle.close().finally(resolve);
        };
        process.on("SIGINT", shutdown);
        process.on("SIGTERM", shutdown);
        if (!enterToRestart) {
            return;
        }
        process.stdin.resume();
        process.stdin.on("data", (chunk) => {
            const text = typeof chunk === "string" ? chunk : chunk.toString("utf8");
            if (!isEnterOnly(text) || closing) {
                return;
            }
            closing = true;
            restartRequested = true;
            clearTerminal();
            process.stdout.write(style.dim("restarting…\n"));
            void handle.close().finally(resolve);
        });
    });
    return restartRequested ? ENTER_RESTART_EXIT_CODE : 0;
}
/** A TCP port from a flag value, or a usage error. */
export function parsePort(value) {
    if (value === undefined) {
        return undefined;
    }
    const port = Number.parseInt(value, 10);
    if (Number.isNaN(port) || port < 0 || port > 65535) {
        throw new CliUsageError(`invalid --port: ${value}`);
    }
    return port;
}
function isEnterOnly(text) {
    return text.length > 0 && Array.from(text).every((ch) => ch === "\n" || ch === "\r");
}
function printServeBanner(handle, opts) {
    const c = stdoutPalette();
    const agents = handle.agents;
    // Name the framework build in the boot line: hosted engines install the
    // published package at provision time, so the serve log is the only
    // durable record of which build a deployment's turns actually ran on.
    const versionTag = c.dim(`(${PACKAGE_NAME} ${packageVersion()})`);
    if (agents.length > 1) {
        process.stdout.write(`${agents.length} agents listening ${versionTag}\n`);
    }
    else {
        const info = agents[0]?.info;
        if (info !== undefined) {
            process.stdout.write(`${info.name} listening ${versionTag}\n`);
        }
    }
    const playgroundUrl = resolvePlaygroundBannerUrl(handle, opts.noPlayground);
    if (playgroundUrl !== undefined) {
        process.stdout.write(`  playground  ${c.cyan(playgroundUrl)}\n`);
    }
    // `/` is only mounted when the playground host home is enabled.
    if (!opts.noPlayground) {
        process.stdout.write(`  home        ${c.cyan(`${handle.url}/`)}\n`);
    }
    // Dev is playground-first (Vite proxies the API). Keep API/route detail for
    // plain `serve`, where operators often curl the HTTP surface directly.
    if (!opts.dev) {
        process.stdout.write(c.dim(`  api  ${handle.url}\n`));
        if (agents.length > 1 || agents[0]?.slug !== "") {
            for (const agent of agents) {
                const info = agent.info;
                process.stdout.write(c.dim(`  /${agent.slug}  ${info.name}\n`));
            }
        }
        else {
            const info = agents[0]?.info;
            if (info !== undefined) {
                process.stdout.write(c.dim(`  POST ${handle.url}/v1/session\n`));
                process.stdout.write(c.dim(`  GET  ${handle.url}/v1/session/:sessionId/stream\n`));
                for (const channel of info.channels) {
                    if (channel.id === "http") {
                        continue;
                    }
                    for (const route of channel.routes) {
                        process.stdout.write(c.dim(`  ${route.method} ${handle.url}${route.url}\n`));
                    }
                }
                if (info.schedules.length > 0) {
                    const scheduleMode = opts.noSchedules ? "disabled" : "running on cron cadence (UTC)";
                    process.stdout.write(c.dim(`  schedules: ${info.schedules.map((s) => s.name).join(", ")} — ${scheduleMode}\n`));
                }
            }
        }
        if (handle.docsUrl !== undefined) {
            process.stdout.write(c.dim(`  docs  ${handle.docsUrl}\n`));
        }
    }
    if (opts.bearerToken) {
        process.stdout.write(c.dim("  auth: bearer token required on API routes (playground has a token field)\n"));
    }
    if (opts.dev) {
        printUnsignedLoopbackNotes(handle);
    }
}
/** Dev accepts unsigned loopback deliveries; say how to verify signatures. */
function printUnsignedLoopbackNotes(handle) {
    const c = stdoutPalette();
    const notes = [
        {
            kind: "github",
            env: "GITHUB_WEBHOOK_SECRET",
            text: `github forward works without a secret; set GITHUB_WEBHOOK_SECRET to verify signatures`,
        },
        {
            kind: "gitlab",
            env: "GITLAB_WEBHOOK_SECRET",
            text: `gitlab replay works without a secret; set GITLAB_WEBHOOK_SECRET to verify X-Gitlab-Token`,
        },
        {
            kind: "bitbucket",
            env: "BITBUCKET_WEBHOOK_SECRET",
            text: `bitbucket replay works without a secret; set BITBUCKET_WEBHOOK_SECRET to verify X-Hub-Signature`,
        },
        {
            kind: "pagerduty",
            env: "PAGERDUTY_WEBHOOK_SECRET",
            text: `pagerduty replay works without a secret; set PAGERDUTY_WEBHOOK_SECRET to verify X-PagerDuty-Signature`,
        },
    ];
    for (const note of notes) {
        const secret = process.env[note.env];
        const declared = handle.agents.some((agent) => agent.info.channels.some((channel) => channel.kind === note.kind));
        if ((secret === undefined || secret === "") && declared) {
            process.stdout.write(c.dim(`  ${note.kind}: dev accepts unsigned loopback deliveries (${CLI} ${note.text})\n`));
        }
    }
}
/** Prefer the Vite playground URL in --dev; otherwise the static SPA path. */
function resolvePlaygroundBannerUrl(handle, noPlayground) {
    if (noPlayground) {
        return undefined;
    }
    if (handle.playgroundDevUrl !== undefined) {
        return handle.playgroundDevUrl.replace(/\/$/, "");
    }
    if (handle.agents.length === 1) {
        return `${handle.agents[0].url}/playground`;
    }
    if (handle.agents.length > 1) {
        return handle.url;
    }
    return undefined;
}
